// Description: Calculation record for invoice amount in MET Customer MDF
public class METCustomerMDFCalculationRecord_InvoiceAmount extends METCustomerMDFCalculationRecord
{
}

Method.Source:
/// <summary>
/// Override to calculate quantity based on WMSOrderTrans
/// </summary>
/// <param name = "_wMSOrderTrans">WMSOrderTrans</param>
/// <returns>Qty</returns>
Amount calcAmount(WMSOrderTrans _wMSOrderTrans)
{
    //todo: check what is the amoutn if partially picked
    return this.getInvoiceAmount(_wMSOrderTrans);
}

/// <summary>
/// Get invoice amount for the given WMSOrderTrans
/// </summary>
/// <param name = "_wMSOrderTrans">WMSOrderTrans</param>
/// <returns>Amount</returns>
private Amount getInvoiceAmount(WMSOrderTrans _wMSOrderTrans)
{
    SalesLine salesLine;
    Amount ret;

    while select firstonly salesLine
        where salesLine.inventTransId == _wMSOrderTrans.inventTransId
    {
        if(customerMDFSetupTable.IncludeTaxesInThreshold)
        {
            ret = ret + salesLine.LineAmount;
        }
        else
        {
            ret = ret + salesLine.lineAmountExclTax();
        }
    }

    return ret;
}

